protected void setInventDim(ItemId _itemId)
{
    mainOrderType           = MobConstants::receive();
    super(_itemId);

    if (mobInventDimSetup.registerLicensePlate())
    {
        //ValidatetoLocation       = true;
        toBin               = '@type='+"@WAX67"+';' + inventDim.LicensePlateId;
    }

}
